```cpp
#include <iostream>
#include <numeric> // For std::accumulate
#include <vector>

int main() {
    int array[4] = {2, 3, 5, 7};
    int size = 4;

    // Calculate the sum of the array elements
    int sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += array[i];
    }

    // Calculate the average
